object-type.inject-code:
{
    QScriptValue funNumCopies = engine->newFunction(
        [](QScriptContext *ctx, QScriptEngine *eng) -> QScriptValue {
            QPrinter *p = qscriptvalue_cast<QPrinter*>(ctx->thisObject());
            if (!p)
                return ctx->throwError(QScriptContext::TypeError,
                    QString::fromLatin1("QPrinter.numCopies(): this object is not a QPrinter"));
            return QScriptValue(eng, p->copyCount());
        }, 0);
    proto.setProperty(QString::fromLatin1("numCopies"), funNumCopies, QScriptValue::SkipInEnumeration);

    QScriptValue funOrientation = engine->newFunction(
        [](QScriptContext *ctx, QScriptEngine *eng) -> QScriptValue {
            QPrinter *p = qscriptvalue_cast<QPrinter*>(ctx->thisObject());
            if (!p)
                return ctx->throwError(QScriptContext::TypeError,
                    QString::fromLatin1("QPrinter.orientation(): this object is not a QPrinter"));
            return qScriptValueFromValue(eng, p->pageLayout().orientation());
        }, 0);
    proto.setProperty(QString::fromLatin1("orientation"), funOrientation, QScriptValue::SkipInEnumeration);

    QScriptValue funSetOrientation = engine->newFunction(
        [](QScriptContext *ctx, QScriptEngine *eng) -> QScriptValue {
            QPrinter *p = qscriptvalue_cast<QPrinter*>(ctx->thisObject());
            if (!p)
                return ctx->throwError(QScriptContext::TypeError,
                    QString::fromLatin1("QPrinter.setOrientation(): this object is not a QPrinter"));
            p->setPageOrientation(qscriptvalue_cast<QPageLayout::Orientation>(ctx->argument(0)));
            return eng->undefinedValue();
        }, 1);
    proto.setProperty(QString::fromLatin1("setOrientation"), funSetOrientation, QScriptValue::SkipInEnumeration);

    QScriptValue funSetPageSizeMM = engine->newFunction(
        [](QScriptContext *ctx, QScriptEngine *eng) -> QScriptValue {
            QPrinter *p = qscriptvalue_cast<QPrinter*>(ctx->thisObject());
            if (!p)
                return ctx->throwError(QScriptContext::TypeError,
                    QString::fromLatin1("QPrinter.setPageSizeMM(): this object is not a QPrinter"));
            p->setPageSize(QPageSize(qscriptvalue_cast<QSizeF>(ctx->argument(0)), QPageSize::Millimeter));
            return eng->undefinedValue();
        }, 1);
    proto.setProperty(QString::fromLatin1("setPageSizeMM"), funSetPageSizeMM, QScriptValue::SkipInEnumeration);

    QScriptValue funSetPageMargins = engine->newFunction(
        [](QScriptContext *ctx, QScriptEngine *eng) -> QScriptValue {
            QPrinter *p = qscriptvalue_cast<QPrinter*>(ctx->thisObject());
            if (!p)
                return ctx->throwError(QScriptContext::TypeError,
                    QString::fromLatin1("QPrinter.setPageMargins(): this object is not a QPrinter"));
            if (ctx->argumentCount() < 5)
                return ctx->throwError(QScriptContext::TypeError,
                    QString::fromLatin1("QPrinter.setPageMargins(): expected left, top, right, bottom, unit"));
            const QMarginsF margins(ctx->argument(0).toNumber(), ctx->argument(1).toNumber(),
                                    ctx->argument(2).toNumber(), ctx->argument(3).toNumber());
            p->setPageMargins(margins, static_cast<QPageLayout::Unit>(ctx->argument(4).toInt32()));
            return eng->undefinedValue();
        }, 1);
    proto.setProperty(QString::fromLatin1("setPageMargins"), funSetPageMargins, QScriptValue::SkipInEnumeration);
}

{
    QScriptValue funIsOptionEnabled = engine->newFunction(
        [](QScriptContext *ctx, QScriptEngine *eng) -> QScriptValue {
            QAbstractPrintDialog *d = qscriptvalue_cast<QAbstractPrintDialog*>(ctx->thisObject());
            if (!d)
                return ctx->throwError(QScriptContext::TypeError,
                    QString::fromLatin1("isOptionEnabled(): this object is not a QAbstractPrintDialog"));
            QPrintDialog *pd = qobject_cast<QPrintDialog*>(d);
            if (!pd)
                return ctx->throwError(QString::fromLatin1("isOptionEnabled() is only available for QPrintDialog in Qt 6"));
            const QAbstractPrintDialog::PrintDialogOption option =
                qscriptvalue_cast<QAbstractPrintDialog::PrintDialogOption>(ctx->argument(0));
            return QScriptValue(eng, pd->testOption(option));
        }, 1);
    proto.setProperty(QString::fromLatin1("isOptionEnabled"), funIsOptionEnabled, QScriptValue::SkipInEnumeration);
}
